import React from 'react'
import styled from 'styled-components'
import { createPortal } from 'react-dom'
import { IoMdAddCircleOutline } from 'react-icons/io'
import { FiChevronDown, FiTag } from 'react-icons/fi'

interface CardTagsProps {
  date: string
  tags: string[]
  availableTags: string[]
  readOnly: boolean

  tagPickerRef: React.RefObject<HTMLDivElement>
  tagDropdownRef: React.RefObject<HTMLDivElement>
  otherTagsDropdownRef: React.RefObject<HTMLDetailsElement>

  showTagPicker: boolean
  creatingTag: boolean
  newTagName: string

  setShowTagPicker: React.Dispatch<React.SetStateAction<boolean>>
  setCreatingTag: React.Dispatch<React.SetStateAction<boolean>>
  setNewTagName: React.Dispatch<React.SetStateAction<string>>
  onDateChange: (date: string) => void

  hasTag: (tag: string) => boolean
  toggleTag: (tag: string) => void
  createTag: (name: string) => void
  formatTag: (tag: string) => string
  formatDate: (date: string) => string
}

const CardTags: React.FC<CardTagsProps> = ({
  date,
  tags,
  availableTags,
  readOnly,
  tagPickerRef,
  tagDropdownRef,
  otherTagsDropdownRef,
  showTagPicker,
  creatingTag,
  newTagName,
  setShowTagPicker,
  setCreatingTag,
  setNewTagName,
  onDateChange,
  hasTag,
  toggleTag,
  createTag,
  formatTag,
  formatDate,
}) => {
  const dateInputRef = React.useRef<HTMLInputElement>(null)
  return (
    <Container>
      <TagList>
        <>
          <DateChip
            $disabled={readOnly}
            aria-disabled={readOnly}
            onClick={() => {
              if (readOnly) return

              dateInputRef.current?.showPicker?.()
              dateInputRef.current?.click()
            }}
          >
            {formatDate(date)}
          </DateChip>

          <input
            ref={dateInputRef}
            type="date"
            value={date}
            style={{ display: 'none' }}
            onChange={(e) => onDateChange(e.target.value)}
          />
        </>
      </TagList>

      {tags.length > 0 && (
        <AssignedTags ref={otherTagsDropdownRef}>
          <AssignedTagsSummary
            aria-label={`Show ${tags.length} note ${tags.length === 1 ? 'tag' : 'tags'}`}
            title={`${tags.length} note ${tags.length === 1 ? 'tag' : 'tags'}`}
          >
            <FiTag />
            <span>{tags.length}</span>
            <FiChevronDown />
          </AssignedTagsSummary>
          <AssignedTagsList>
            {tags.map((tag) => (
              <TagChip key={tag} type="button" disabled={readOnly} onClick={() => toggleTag(tag)}>
                {formatTag(tag)}
              </TagChip>
            ))}
          </AssignedTagsList>
        </AssignedTags>
      )}

      <TagPicker ref={tagPickerRef}>
        {!readOnly && (
          <TagPickerButton
            type="button"
            title="Add tag"
            aria-label="Add tag"
            onClick={() => setShowTagPicker(!showTagPicker)}
          >
            <IoMdAddCircleOutline />
          </TagPickerButton>
        )}

        {showTagPicker &&
          createPortal(
            <TagDropdown ref={tagDropdownRef}>
              {availableTags.map((tag) => (
                <TagOption
                  key={tag}
                  className={hasTag(tag) ? 'selected' : ''}
                  onClick={() => {
                    if (!readOnly) {
                      toggleTag(tag)
                    }
                  }}
                >
                  <FiTag />
                  <span>{formatTag(tag)}</span>
                </TagOption>
              ))}

              {!creatingTag ? (
                <NewTagButton onClick={() => !readOnly && setCreatingTag(true)}>
                  <FiTag />
                  New Tag
                </NewTagButton>
              ) : (
                <NewTagInput
                  autoFocus
                  placeholder="Tag name..."
                  value={newTagName}
                  onChange={(e) => !readOnly && setNewTagName(e.target.value)}
                  onKeyDown={(e) => {
                    if (!readOnly && e.key === 'Enter') {
                      createTag(newTagName)
                    }

                    if (e.key === 'Escape') {
                      setCreatingTag(false)
                      setNewTagName('')
                    }
                  }}
                  onBlur={() => {
                    if (readOnly) {
                      setCreatingTag(false)
                      setNewTagName('')
                      return
                    }

                    if (newTagName.trim()) {
                      createTag(newTagName)
                    } else {
                      setCreatingTag(false)
                    }
                  }}
                />
              )}
            </TagDropdown>,
            document.body
          )}
      </TagPicker>
    </Container>
  )
}

export default CardTags

